create temp table wh_members on commit drop as
select
    item ->> 'canonicalKey' as canonical_key,
    (item ->> 'memberId')::uuid as member_id,
    item ->> 'paxName' as pax_name,
    (item ->> 'firstPostDate')::date as first_post_date,
    (item ->> 'isDoge')::boolean as is_doge
from wh_payload payload
cross join lateral jsonb_array_elements(payload.document -> 'members') member(item);

alter table wh_members add primary key (canonical_key);
create unique index wh_members_member_id_unique on wh_members(member_id);

create temp table wh_sessions on commit drop as
select
    item ->> 'sessionKey' as session_key,
    (item ->> 'sessionId')::uuid as session_id,
    (item ->> 'date')::date as session_date,
    item ->> 'aoName' as ao_name,
    (item ->> 'aoId')::uuid as ao_id,
    (item ->> 'siteId')::uuid as site_id,
    nullif(item ->> 'eventName', '') as event_name,
    item ->> 'workoutType' as workout_type,
    item -> 'attendeeKeys' as attendee_keys,
    item -> 'qAssignments' as q_assignments,
    item -> 'fngs' as fngs
from wh_payload payload
cross join lateral jsonb_array_elements(payload.document -> 'sessions') session(item);

alter table wh_sessions add primary key (session_key);
create unique index wh_sessions_session_id_unique on wh_sessions(session_id);

create temp table wh_demo_members on commit drop as
select value::uuid as member_id
from wh_payload payload
cross join lateral jsonb_array_elements_text(payload.document #> '{demo,memberIds}') item(value);

create temp table wh_demo_sessions on commit drop as
select value::uuid as session_id
from wh_payload payload
cross join lateral jsonb_array_elements_text(payload.document #> '{demo,sessionIds}') item(value);

create temp table wh_demo_late_session_dates on commit drop as
select value::date as session_date
from wh_payload payload
cross join lateral jsonb_array_elements_text(payload.document #> '{demo,lateSessionDates}') item(value);

create temp table wh_expected_aos on commit drop as
select (item ->> 'id')::uuid as id, item ->> 'name' as name
from wh_payload payload
cross join lateral jsonb_array_elements(payload.document #> '{configuration,aos}') ao(item);

create temp table wh_expected_sites on commit drop as
select (item ->> 'id')::uuid as id, item ->> 'name' as name
from wh_payload payload
cross join lateral jsonb_array_elements(payload.document #> '{configuration,sites}') site(item);

do $validation$
declare
    contract jsonb;
begin
    select document -> 'contract' into contract from wh_payload;
    if contract ->> 'schemaVersion' <> 'west-houston-one-time-migration-v1'
       or contract ->> 'regionId' <> '7298b632-4d9a-542f-b65d-d416e5c1e631'
       or contract ->> 'canonicalSha256' <> 'f1c677cf99e8aa9e15595d4ed3fb796f2d624d741868395786b097108114c16a'
       or contract ->> 'humanManifestSha256' <> 'aba7d5a90ff8e8e4d1e3c280aee2f112cd620f5877ffc651ff23ebcf240833c2'
       or contract ->> 'demoManifestSha256' <> 'ee1e1523b74e8336076d7c1f07d2cd407c8ed6d73e2065282fbef0f5807a5d36' then
        raise exception 'West Houston embedded payload contract mismatch';
    end if;

    if (select count(*) from wh_members) <> 1194
       or (select count(*) from wh_members where not is_doge) <> 1193
       or (select count(*) from wh_members where is_doge) <> 1
       or (select count(*) from wh_sessions) <> 3742
       or (select count(*) from wh_demo_members) <> 219
       or (select count(*) from wh_demo_sessions) <> 314
       or (select count(*) from wh_demo_late_session_dates) <> 2 then
        raise exception 'West Houston embedded payload counts are invalid';
    end if;

    if (select member_id from wh_members where is_doge) <>
       '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid then
        raise exception 'DOGE canonical mapping changed';
    end if;

    if (select count(distinct member_id) from wh_members where canonical_key in (
        'wh-canonical-member-ba141425b009841ed440',
        'wh-canonical-member-d9670249013c1aabc599'
    )) <> 2 then
        raise exception 'WH-ID-009 is not represented by two independent identities';
    end if;

    if (select coalesce(sum(jsonb_array_length(attendee_keys)), 0) from wh_sessions) <> 43132
       or (select coalesce(sum(jsonb_array_length(q_assignments)), 0) from wh_sessions) <> 3636
       or (select coalesce(sum(jsonb_array_length(fngs)), 0) from wh_sessions) <> 494 then
        raise exception 'West Houston relationship payload counts are invalid';
    end if;
end;
$validation$;

select region.id
from public.regions region
where region.id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
for update;

do $preflight$
begin
    if not exists (
        select 1 from public.regions region
        where region.id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
          and region.name = 'F3 West Houston'
          and region.environment = 'production'
    ) then
        raise exception 'West Houston production region contract mismatch';
    end if;

    if exists (
        (select ao.id, ao.name from public.aos ao
         where ao.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
         except select id, name from wh_expected_aos)
        union all
        (select id, name from wh_expected_aos
         except select ao.id, ao.name from public.aos ao
         where ao.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid)
    ) then
        raise exception 'West Houston AO configuration differs from the approved configuration';
    end if;

    if exists (
        (select site.id, site.name from public.sites site
         where site.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
         except select id, name from wh_expected_sites)
        union all
        (select id, name from wh_expected_sites
         except select site.id, site.name from public.sites site
         where site.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid)
    ) then
        raise exception 'West Houston site configuration differs from the approved configuration';
    end if;

    if not exists (
        select 1 from public.members member
        where member.id = '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid
          and member.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
          and member.status = 'active'
          and regexp_replace(lower(coalesce(member.pax_name, '')), '[^a-z0-9]+', '', 'g') = 'doge'
    ) then
        raise exception 'DOGE existing canonical member contract mismatch';
    end if;

    if (select count(*) from public.profiles profile
        where profile.member_id = '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid) <> 1 then
        raise exception 'DOGE must have exactly one existing profile';
    end if;

    if (select count(*)
        from public.profiles profile
        join public.members member on member.id = profile.member_id
        where member.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid) <> 1 then
        raise exception 'West Houston must have exactly one registered profile and it must belong to DOGE';
    end if;

    if not exists (
        select 1 from public.region_access access
        join public.profiles profile on profile.id = access.user_id
        where access.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
          and profile.member_id = '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid
    ) then
        raise exception 'DOGE must retain existing West Houston access';
    end if;

    if exists (
        select target.session_date
        from wh_demo_late_session_dates target
        left join public.sessions session
          on session.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
         and session.date = target.session_date::text
        group by target.session_date
        having count(session.id) <> 1
    ) then
        raise exception 'Each approved late demo date must identify exactly one West Houston session';
    end if;

    insert into wh_demo_sessions (session_id)
    select session.id
    from wh_demo_late_session_dates target
    join public.sessions session
      on session.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
     and session.date = target.session_date::text;

    if (select count(*) from wh_demo_sessions) <> 316
       or (select count(distinct session_id) from wh_demo_sessions) <> 316 then
        raise exception 'West Houston disposable demo-session allowlist did not resolve to exactly 316 sessions';
    end if;

    if exists (
        (select session.id from public.sessions session
         where session.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
         except select session_id from wh_demo_sessions)
        union all
        (select session_id from wh_demo_sessions
         except select session.id from public.sessions session
         where session.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid)
    ) then
        raise exception 'West Houston sessions are not the exact approved demo set';
    end if;

    if exists (
        (select member.id from public.members member
         where member.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
         except select member_id from wh_demo_members)
        union all
        (select member_id from wh_demo_members
         except select member.id from public.members member
         where member.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid)
    ) then
        raise exception 'West Houston members are not the exact approved demo set';
    end if;

    if exists (
        select 1 from public.profiles profile
        join wh_demo_members demo on demo.member_id = profile.member_id
        where demo.member_id <> '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid
    ) then
        raise exception 'A deletable demo member is linked to a profile';
    end if;

    if exists (
        select 1 from public.region_participants participant
        join wh_demo_members demo on demo.member_id = participant.member_id
        where demo.member_id <> '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid
          and participant.region_id <> '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
    ) then
        raise exception 'A deletable demo member has cross-region participation';
    end if;

    if exists (
        select 1 from public.sessions session
        where session.region_id <> '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
          and (
              exists (
                  select 1
                  from jsonb_array_elements_text(coalesce(session.attendee_ids, '[]'::jsonb)) attendee(value)
                  join wh_demo_members demo on demo.member_id = attendee.value::uuid
                  where demo.member_id <> '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid
              )
              or session.q_id in (
                  select member_id from wh_demo_members
                  where member_id <> '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid
              )
              or coalesce(session.q_ids, '{}'::uuid[]) && array(
                  select member_id from wh_demo_members
                  where member_id <> '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid
              )
              or exists (
                  select 1 from jsonb_array_elements(coalesce(session.fngs, '[]'::jsonb)) fng(value)
                  join wh_demo_members demo on demo.member_id = coalesce(
                      nullif(fng.value ->> 'memberId', '')::uuid,
                      nullif(fng.value ->> 'member_id', '')::uuid
                  )
                  where demo.member_id <> '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid
              )
          )
    ) then
        raise exception 'A deletable demo member is referenced by a non-West-Houston session';
    end if;

    if exists (
        select 1 from public.member_inviters inviter
        where (
            inviter.member_id in (
                select member_id from wh_demo_members
                where member_id <> '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid
            )
            and inviter.inviter_member_id not in (
                select member_id from wh_demo_members
                where member_id <> '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid
            )
        ) or (
            inviter.inviter_member_id in (
                select member_id from wh_demo_members
                where member_id <> '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid
            )
            and inviter.member_id not in (
                select member_id from wh_demo_members
                where member_id <> '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid
            )
        )
    ) then
        raise exception 'A deletable demo member has an inviter relationship outside the demo set';
    end if;

    if exists (
        select 1 from public.member_stats_baselines baseline
        where baseline.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
    ) then
        raise exception 'West Houston has unexpected member-stat baselines';
    end if;

    if exists (
        select 1 from wh_members canonical
        join public.members member on member.id = canonical.member_id
        where not canonical.is_doge
    ) then
        raise exception 'A deterministic canonical member UUID already exists';
    end if;

    if exists (
        select 1 from wh_sessions canonical
        join public.sessions session on session.id = canonical.session_id
    ) then
        raise exception 'A deterministic canonical session UUID already exists';
    end if;
end;
$preflight$;

create temp table wh_preserved_snapshot (
    object_name text primary key,
    snapshot jsonb
) on commit drop;

insert into wh_preserved_snapshot (object_name, snapshot)
values
    ('region', (
        select to_jsonb(region) from public.regions region
        where region.id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
    )),
    ('aos', (
        select jsonb_agg(to_jsonb(ao) order by ao.id) from public.aos ao
        where ao.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
    )),
    ('sites', (
        select jsonb_agg(to_jsonb(site) order by site.id) from public.sites site
        where site.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
    )),
    ('doge_member_except_first_post', (
        select to_jsonb(member) - 'first_post_date' from public.members member
        where member.id = '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid
    )),
    ('doge_profiles', (
        select jsonb_agg(to_jsonb(profile) order by profile.id) from public.profiles profile
        where profile.member_id = '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid
    )),
    ('region_access', (
        select jsonb_agg(to_jsonb(access) order by access.user_id) from public.region_access access
        where access.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
    ));

create temp table wh_context on commit drop as
select profile.id as doge_profile_id
from public.profiles profile
where profile.member_id = '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid;

create temp table wh_deleted_session_ids (id uuid primary key) on commit drop;
with deleted as (
    delete from public.sessions session
    using wh_demo_sessions demo
    where session.id = demo.session_id
    returning session.id
)
insert into wh_deleted_session_ids select id from deleted;

do $deleted_sessions$
begin
    if (select count(*) from wh_deleted_session_ids) <> 316 then
        raise exception 'Deleted demo session count mismatch';
    end if;
end;
$deleted_sessions$;

-- Region participation is derived again from the approved canonical history.
-- This removes only relationships owned by the exact demo-member allowlist;
-- DOGE's profile and region access are separate and remain untouched.
delete from public.region_participants participant
using wh_demo_members demo
where participant.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
  and participant.member_id = demo.member_id;

create temp table wh_deleted_member_ids (id uuid primary key) on commit drop;
with deleted as (
    delete from public.members member
    using wh_demo_members demo
    where member.id = demo.member_id
      and member.id <> '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid
    returning member.id
)
insert into wh_deleted_member_ids select id from deleted;

do $deleted_members$
begin
    if (select count(*) from wh_deleted_member_ids) <> 218 then
        raise exception 'Deleted demo member count mismatch';
    end if;
end;
$deleted_members$;

insert into public.members (
    id, region_id, pax_name, real_name, first_post_date, status
)
select
    canonical.member_id,
    '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid,
    canonical.pax_name,
    null,
    canonical.first_post_date::text,
    'active'
from wh_members canonical
where not canonical.is_doge
order by canonical.canonical_key;

update public.members member
set first_post_date = case
    when nullif(btrim(member.first_post_date), '') is null then canonical.first_post_date::text
    when canonical.first_post_date < member.first_post_date::date then canonical.first_post_date::text
    else member.first_post_date
end
from wh_members canonical
where canonical.is_doge
  and member.id = canonical.member_id;

do $identity_participants$
declare
    canonical_member record;
    doge_profile_id uuid;
begin
    select context.doge_profile_id into doge_profile_id from wh_context context;
    for canonical_member in
        select member_id from wh_members order by canonical_key
    loop
        perform public.upsert_region_participant(
            '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid,
            canonical_member.member_id,
            null,
            'historic_import',
            doge_profile_id
        );
    end loop;
end;
$identity_participants$;

create temp table wh_expected_sessions on commit drop as
select
    source.session_key,
    source.session_id,
    source.session_date,
    source.ao_name,
    source.ao_id,
    source.site_id,
    source.event_name,
    coalesce((
        select jsonb_agg(member.member_id::text order by member.member_id)
        from jsonb_array_elements_text(source.attendee_keys) attendee(member_key)
        join wh_members member on member.canonical_key = attendee.member_key
    ), '[]'::jsonb) as attendee_ids,
    coalesce((
        select array_agg(member.member_id order by member.member_id)
        from jsonb_array_elements(source.q_assignments) assignment(value)
        join wh_members member on member.canonical_key = assignment.value ->> 'memberKey'
    ), '{}'::uuid[]) as q_ids,
    (
        select member.member_id
        from jsonb_array_elements(source.q_assignments) assignment(value)
        join wh_members member on member.canonical_key = assignment.value ->> 'memberKey'
        order by case when assignment.value ->> 'role' = 'q' then 0 else 1 end, member.member_id
        limit 1
    ) as q_id,
    coalesce((
        select jsonb_agg(
            jsonb_build_object(
                'memberId', member.member_id::text,
                'paxName', fng.value ->> 'paxName'
            ) order by member.member_id
        )
        from jsonb_array_elements(source.fngs) fng(value)
        join wh_members member on member.canonical_key = fng.value ->> 'memberKey'
    ), '[]'::jsonb) as fngs
from wh_sessions source;

insert into public.sessions (
    id, region_id, date, ao_name, q_id, attendee_ids, fngs, notes,
    created_at, q_ids, created_by_user_id, start_time,
    attendance_review_status, ao_id, site_id
)
select
    expected.session_id,
    '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid,
    expected.session_date::text,
    expected.ao_name,
    expected.q_id,
    expected.attendee_ids,
    expected.fngs,
    expected.event_name,
    floor(extract(epoch from expected.session_date::timestamptz) * 1000)::bigint,
    expected.q_ids,
    context.doge_profile_id,
    null,
    'not_required',
    expected.ao_id,
    expected.site_id
from wh_expected_sessions expected
cross join wh_context context
order by expected.session_date, expected.session_id;

do $participant_sync$
declare
    target_session record;
begin
    for target_session in
        select session_id from wh_expected_sessions order by session_date, session_id
    loop
        perform public.sync_region_participants_for_session(target_session.session_id);
    end loop;
end;
$participant_sync$;

select public.rebuild_member_stats_for_region(
    '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
);

do $reconciliation$
declare
    actual_attendance bigint;
    actual_qs bigint;
    actual_fngs bigint;
begin
    if exists (
        (select member.id from public.members member
         where member.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
         except select member_id from wh_members)
        union all
        (select member_id from wh_members
         except select member.id from public.members member
         where member.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid)
    ) then
        raise exception 'Final canonical member UUID set mismatch';
    end if;

    if exists (
        select 1 from wh_members expected
        join public.members actual on actual.id = expected.member_id
        where (not expected.is_doge and actual.pax_name is distinct from expected.pax_name)
           or actual.status <> 'active'
           or actual.region_id <> '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
           or actual.first_post_date::date > expected.first_post_date
           or (not expected.is_doge and actual.first_post_date::date <> expected.first_post_date)
    ) then
        raise exception 'Final canonical member attributes mismatch';
    end if;

    if exists (
        (select session.id from public.sessions session
         where session.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
         except select session_id from wh_expected_sessions)
        union all
        (select session_id from wh_expected_sessions
         except select session.id from public.sessions session
         where session.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid)
    ) then
        raise exception 'Final canonical session UUID set mismatch';
    end if;

    if exists (
        select 1
        from wh_expected_sessions expected
        join public.sessions actual on actual.id = expected.session_id
        where actual.region_id <> '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
           or actual.date <> expected.session_date::text
           or actual.ao_name is distinct from expected.ao_name
           or actual.ao_id is distinct from expected.ao_id
           or actual.site_id is distinct from expected.site_id
           or actual.q_id is distinct from expected.q_id
           or coalesce(actual.q_ids, '{}'::uuid[]) is distinct from expected.q_ids
           or coalesce(actual.attendee_ids, '[]'::jsonb) is distinct from expected.attendee_ids
           or coalesce(actual.fngs, '[]'::jsonb) is distinct from expected.fngs
    ) then
        raise exception 'Final canonical session mapping or content mismatch';
    end if;

    select
        coalesce(sum(jsonb_array_length(coalesce(session.attendee_ids, '[]'::jsonb))), 0),
        coalesce(sum(cardinality(coalesce(session.q_ids, '{}'::uuid[]))), 0),
        coalesce(sum(jsonb_array_length(coalesce(session.fngs, '[]'::jsonb))), 0)
    into actual_attendance, actual_qs, actual_fngs
    from public.sessions session
    where session.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid;

    if actual_attendance <> 43132 or actual_qs <> 3636 or actual_fngs <> 494 then
        raise exception 'Final relationship totals mismatch: attendance %, Q/VQ %, FNG %',
            actual_attendance, actual_qs, actual_fngs;
    end if;

    if exists (
        select 1 from public.sessions session
        cross join lateral jsonb_array_elements(coalesce(session.fngs, '[]'::jsonb)) fng(value)
        where session.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
          and not (coalesce(session.attendee_ids, '[]'::jsonb) ? (fng.value ->> 'memberId'))
    ) then
        raise exception 'A final FNG is absent from attendance';
    end if;

    if exists (
        select 1 from public.sessions session
        cross join lateral jsonb_array_elements(coalesce(session.fngs, '[]'::jsonb)) fng(value)
        where session.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
          and (fng.value ->> 'memberId')::uuid = any(coalesce(session.q_ids, '{}'::uuid[]))
    ) then
        raise exception 'A final session contains a Q/FNG contradiction';
    end if;

    if exists (
        select 1
        from wh_members expected
        left join public.member_stats stats
          on stats.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
         and stats.member_id = expected.member_id
        left join lateral (
            select count(*)::integer as total_posts, max(session.session_date) as last_post
            from wh_expected_sessions session
            where session.attendee_ids ? expected.member_id::text
        ) posts on true
        left join lateral (
            select count(*)::integer as total_qs, max(session.session_date) as last_q
            from wh_expected_sessions session
            where expected.member_id = any(session.q_ids)
        ) qs on true
        where (
            coalesce(posts.total_posts, 0) > 0
            and (
                stats.member_id is null
                or stats.total_posts <> posts.total_posts
                or stats.total_qs <> coalesce(qs.total_qs, 0)
                or stats.last_post_date is distinct from posts.last_post
                or stats.last_q_date is distinct from qs.last_q
                or stats.first_post_date is distinct from (
                    select member.first_post_date::date from public.members member
                    where member.id = expected.member_id
                )
            )
        ) or (
            coalesce(posts.total_posts, 0) = 0
            and stats.member_id is not null
        )
    ) then
        raise exception 'Rebuilt West Houston member statistics differ from canonical aggregates';
    end if;

    if exists (
        select 1
        from wh_members expected
        left join public.region_participants participant
          on participant.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
         and participant.member_id = expected.member_id
        left join lateral (
            select min(session.session_date) as first_participated,
                   max(session.session_date) as last_participated
            from wh_expected_sessions session
            where session.attendee_ids ? expected.member_id::text
        ) attendance on true
        left join lateral (
            select count(*) as q_count
            from wh_expected_sessions session
            where expected.member_id = any(session.q_ids)
        ) q_history on true
        where participant.member_id is null
           or participant.status <> 'active'
           or not ('historic_import' = any(participant.sources))
           or participant.first_participated_on is distinct from attendance.first_participated
           or participant.last_participated_on is distinct from attendance.last_participated
           or (q_history.q_count > 0 and not ('q_history' = any(participant.sources)))
           or (attendance.first_participated is not null and not ('session_attendance' = any(participant.sources)))
    ) then
        raise exception 'West Houston region-participant reconciliation differs from canonical history';
    end if;

    if (select count(*) from public.region_participants participant
        where participant.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid) <> 1194 then
        raise exception 'Final West Houston region-participant count mismatch';
    end if;

    if (select snapshot from wh_preserved_snapshot where object_name = 'region') is distinct from
       (select to_jsonb(region) from public.regions region
        where region.id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid)
       or (select snapshot from wh_preserved_snapshot where object_name = 'aos') is distinct from
       (select jsonb_agg(to_jsonb(ao) order by ao.id) from public.aos ao
        where ao.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid)
       or (select snapshot from wh_preserved_snapshot where object_name = 'sites') is distinct from
       (select jsonb_agg(to_jsonb(site) order by site.id) from public.sites site
        where site.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid)
       or (select snapshot from wh_preserved_snapshot where object_name = 'doge_member_except_first_post') is distinct from
       (select to_jsonb(member) - 'first_post_date' from public.members member
        where member.id = '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid)
       or (select snapshot from wh_preserved_snapshot where object_name = 'doge_profiles') is distinct from
       (select jsonb_agg(to_jsonb(profile) order by profile.id) from public.profiles profile
        where profile.member_id = '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid)
       or (select snapshot from wh_preserved_snapshot where object_name = 'region_access') is distinct from
       (select jsonb_agg(to_jsonb(access) order by access.user_id) from public.region_access access
        where access.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid) then
        raise exception 'Protected West Houston configuration, DOGE identity, or access changed unexpectedly';
    end if;
end;
$reconciliation$;

commit;
